import { defineComponent, h, type PropType } from 'vue';
import { getMessageStyleKeys, messageStyleKeys } from '../lib/core';
import type { MessageAlign } from '../lib/core';
import styles from './message.module.scss';

export const MessageGroup = defineComponent({
	name: 'MessageGroup',
	setup(_props, { slots }) {
		return () => h('div', { 'data-slot': 'message-group', class: styles[messageStyleKeys.group] }, slots.default?.());
	},
});

export const Message = defineComponent({
	name: 'Message',
	props: {
		align: { type: String as PropType<MessageAlign>, default: 'start' },
	},
	setup(props, { slots }) {
		return () => {
			const styleKeys = getMessageStyleKeys(props.align);
			return h('div', { 'data-slot': 'message', 'data-align': props.align, class: [styles[styleKeys.base], styles[styleKeys.align]] }, slots.default?.());
		};
	},
});

export const MessageAvatar = defineComponent({
	name: 'MessageAvatar',
	setup(_props, { slots }) {
		return () => h('div', { 'data-slot': 'message-avatar', class: styles[messageStyleKeys.avatar] }, slots.default?.());
	},
});

export const MessageContent = defineComponent({
	name: 'MessageContent',
	setup(_props, { slots }) {
		return () => h('div', { 'data-slot': 'message-content', class: styles[messageStyleKeys.content] }, slots.default?.());
	},
});

export const MessageHeader = defineComponent({
	name: 'MessageHeader',
	setup(_props, { slots }) {
		return () => h('div', { 'data-slot': 'message-header', class: styles[messageStyleKeys.header] }, slots.default?.());
	},
});

export const MessageFooter = defineComponent({
	name: 'MessageFooter',
	setup(_props, { slots }) {
		return () => h('div', { 'data-slot': 'message-footer', class: styles[messageStyleKeys.footer] }, slots.default?.());
	},
});

export default Message;

@use '../../../styles/variables/colors' as *;

// 消息组
.group {
	display: flex;
	width: 100%;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-2;
}

// 消息行
.message {
	position: relative;
	display: flex;
	width: 100%;
	min-width: 0;
	gap: $spacing-2;
	font-size: $text-sm;

	&.alignEnd {
		flex-direction: row-reverse;
	}
}

// 消息头像
.avatar {
	display: flex;
	width: 2rem;
	height: 2rem;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	align-self: flex-end;
	overflow: hidden;
	border-radius: $radius-full;
	background-color: var(--tile-message-avatar-background, $muted);
}

// 消息内容
.content {
	display: flex;
	flex: 1;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-2_5;
	overflow-wrap: anywhere;
	word-break: break-word;
}

// 消息头部
.header {
	display: flex;
	max-width: 100%;
	min-width: 0;
	align-items: center;
	padding-inline: $spacing-3;
	font-size: $text-xs;
	font-weight: $font-medium;
	color: var(--tile-message-meta-color, $muted-foreground);
}

// 消息底部
.footer {
	display: flex;
	max-width: 100%;
	min-width: 0;
	align-items: center;
	padding-inline: $spacing-3;
	font-size: $text-xs;
	font-weight: $font-medium;
	color: var(--tile-message-meta-color, $muted-foreground);

	.message.alignEnd & {
		justify-content: flex-end;
	}
}

// 对齐到末端时，内容区内直接子元素右对齐
.message.alignEnd .content > * {
	align-self: flex-end;
}

.message.alignEnd .content {
	align-items: flex-end;
	text-align: end;
}
